content.content:
// Package trailprensure repairs missing backing proposals after branch pushes.
package trailprensure

import (
	"context"
	"fmt"
	"strings"

	"github.com/entirehq/entire-api/internal/store"
	"github.com/entirehq/entire-api/internal/trailforge"
)

// Store is the persistence surface needed by Ensurer.
type Store interface {
	GitHubFullName(ctx context.Context, repoID string) (string, error)
	LinkOpenTrailGhPrIDIfUnchanged(ctx context.Context, repoID, trailID string, expectedProposalID *int, proposalID int) (bool, error)
}

// Ensurer creates and links missing trail proposals.
type Ensurer struct {
	store Store
	forge trailforge.ForgeSync
}

// New constructs an Ensurer.
func New(st Store, forge trailforge.ForgeSync) *Ensurer {
	return &Ensurer{store: st, forge: forge}
}

// EnsureTrailProposal creates missing proposals and removes orphaned shadows.

